  if (state.page === 'dump') $('#main .footer-note').insertAdjacentHTML('beforebegin', `<div class="divider"></div>${panel('Offline pointer research', `<div class="panel-pad"><div class="form-grid"><label>RAM capture<select id="pointer-dump">${state.dumps.map(d => `<option value="${d.id}">${esc(d.created.slice(0, 19))}</option>`).join('')}</select></label><label>Target address<input id="pointer-target" value="0x100000100"></label><label>Maximum depth<select id="pointer-depth"><option>1</option><option>2</option><option selected>3</option><option>4</option><option>5</option></select></label><label>Maximum offset<input id="pointer-max-offset" type="number" value="4096" min="0" max="1048576"></label></div><p class="note">Search backward through 64-bit pointers to find candidate chains. Results include region-relative roots. Validate each chain against another capture or game launch before building it into a trainer.</p><div class="row">${button('pointer-search', 'Find pointer chains', 'link', 'primary')}${button('pointer-cancel', 'Cancel', null, 'ghost')}${button('pointer-results', 'Show first 100', null, 'ghost')}</div><div class="divider"></div><div id="pointer-progress">${progress(state.status.pointers)}</div><pre id="pointer-output" class="output hidden"></pre></div>`, 'link')}`);
