async function refreshProcesses() { state.processes = await api('processes'); if (!state.processes.some(p => p.pid === state.pid)) state.pid = state.processes.find(p => p.name.includes('eboot'))?.pid || 0; $('#process').innerHTML = processOptions(); if (state.pid) await refreshMaps(); }
async function refreshMaps() { if (!state.pid) throw new Error('Select a process first'); state.maps = await api('maps', { pid: state.pid }); state.selected.clear(); }
async function connect(demo = false) { state.status = await api('connect', { demo }); state.session = null; state.results = null; state.hex = null; state.dumpId = ''; await refreshProcesses(); state.page = demo ? 'memory' : 'home'; shell(); toast(demo ? 'Memory lab ready. Health is 100 at 0x100000100.' : 'Connected to '+debuggerName()); }
async function newScan(refine) {
  const args = { pid: state.pid, dumpId: state.dumpId || undefined, backend: $('#scan-backend').value, type: $('#scan-type').value, mode: $('#scan-mode').value, value: $('#scan-value').value, value2: $('#scan-value2').value, epsilon: Number($('#scan-epsilon').value), start: $('#scan-start').value || undefined, end: $('#scan-end').value || undefined, alignment: Number($('#scan-align').value) || (['aob', 'text'].includes($('#scan-type').value) ? 1 : undefined), writableOnly: $('#writable-only').checked };
  if (refine) { if (!state.session) throw new Error('Run an initial scan first'); args.sessionId = state.session; }
  state.status.scan = await api('scan_start', args); state.offset = 0; $('#scan-progress').innerHTML = progress(state.status.scan);
}
async function readHex() { state.previousHex = state.hex; state.hex = await api('memory_read', { pid: state.pid || undefined, address: $('#hex-address').value, length: Number($('#hex-length').value), dumpId: state.dumpId || undefined }); $('#hex-output').innerHTML = hexView(); }
function inspector(result) { state.inspectorOutput = JSON.stringify(result, null, 2); $('#inspector-extra').textContent = state.inspectorOutput; $('#inspector-extra').classList.remove('hidden'); }
async function getResults() { state.results = await api('scan_results', { sessionId: state.session, offset: state.offset, limit: 100 }); if ($('#scan-results')) { $('#scan-results').innerHTML = resultsView(); $('#result-meta').textContent = `${state.results.count.toLocaleString()} candidates · pass ${state.results.pass} · ${state.results.backend || 'host'} · offset ${state.offset}`; } }
async function addWatch(a) { if (state.dumpId) throw new Error('Watches read live memory; leave offline dump mode first'); const type = state.results?.type || $('#scan-type').value; if (['aob', 'text'].includes(type)) throw new Error('Choose a numeric type for watches'); await api('watch_add', { pid: state.pid, address: a, type, label: 'Watch ' + a }); state.watches = await api('watch_read'); $('#watch-results').innerHTML = watchView(); toast('Watch saved with region-relative offset'); }
async function startDump(args) { if (state.dumpId && state.page === 'memory') throw new Error('This source is already an offline dump'); state.status.dump = await api('dump_start', { pid: state.pid, ...args }); state.page = 'dump'; shell(); }
