async function chooseFile() { if (window.desktop) return window.desktop.chooseFile(); throw new Error('File selection is available in the desktop app. For payloads you can enter an absolute local path.'); }
document.addEventListener('click', async e => {
  const b = e.target.closest('button'); if (!b) return;
  try {
    if (b.dataset.page) { state.page = b.dataset.page; shell(); return; }
    b.disabled = true;
    if (b.dataset.consoleAction) await consoleAction(b.dataset.consoleAction,b.dataset.titleId);
    else if(b.dataset.saveDecrypt){await api('console_backup',{id:b.dataset.saveDecrypt,decrypted:true});await refreshConsole();}
    else if(b.dataset.savePrepare){if(!window.desktop?.chooseFolder)throw Error('Use the desktop app to choose an edited save folder');const folder=await window.desktop.chooseFolder();if(folder){await api('console_save_restore',{id:b.dataset.savePrepare,folder});await refreshConsole();}}
    else if(b.dataset.saveDiscard){await api('console_save_discard',{planId:b.dataset.saveDiscard});await refreshConsole();}
    else if(b.dataset.saveApply){if(await window.desktop?.confirmSaveRestore({planId:b.dataset.saveApply})){await api('console_save_restore',{id:b.dataset.saveId,planId:b.dataset.saveApply,confirmation:b.dataset.saveId});await refreshConsole();}}
    else if (b.dataset.consoleBackup) {await api('console_backup',{id:b.dataset.consoleBackup});await refreshConsole();}
    else if (b.dataset.address) { $('#hex-address').value = b.dataset.address; await readHex(); }
    else if (b.dataset.watch) await addWatch(b.dataset.watch);
    else if (b.dataset.removeWatch) { await api('watch_remove', { id: b.dataset.removeWatch }); state.watches = await api('watch_read'); $('#watch-results').innerHTML = watchView(); }
    else if (b.dataset.range) { state.page = 'memory'; state.dumpId = ''; shell(); $('#scan-start').value = b.dataset.range; $('#scan-end').value = b.dataset.end; $('#main details').open = true; }
    else if (b.dataset.offline) { state.dumpId = b.dataset.offline; state.session = null; state.results = null; state.hex = null; state.page = 'memory'; shell(); }
    else if (b.dataset.folder) { $('#ftp-path').value = state.ftpPath.replace(/\/$/, '') + '/' + b.dataset.folder; await handlers['ftp-list'](); }
    else if(b.dataset.shadowRemove){await api('shadow_remove',{id:b.dataset.shadowRemove});await refreshShadow();}
    else if(b.dataset.shadowAction){const action=b.dataset.shadowAction,titleId=b.dataset.shadowTitle;const approved=window.desktop?await window.desktop.confirmConsole({action,titleId}):window.confirm(action+' '+titleId+'?');if(approved){await api('shadow_action',{action,titleId,confirmation:titleId});toast('Game action accepted');await refreshShadow(true);}}
    else if (b.dataset.pkgRemove) {await api('pkg_queue_remove',{id:b.dataset.pkgRemove});await refreshPackages();}
    else if (b.dataset.download) { toast('Downloading ' + b.dataset.download); const r = await api('ftp_download', { remote: state.ftpPath.replace(/\/$/, '') + '/' + b.dataset.download }); toast('Saved: ' + r.local); }
    else if (handlers[b.id]) await handlers[b.id]();
  } catch (err) { toast(err.message, true); }
  finally { b.disabled = false; }
});
document.addEventListener('input',e=>{if(e.target.id==='shadow-search'){state.shadowSearch=e.target.value;$('#shadow-library').innerHTML=shadowLibrary();}if(e.target.id==='console-search'){state.consoleSearch=e.target.value;$('#console-games').innerHTML=consoleGames();}});
document.addEventListener('change', async e => {
  try {
    if (e.target.id === 'console-platform') { $('#payload-port').value=e.target.value==='ps5'?9021:9090; $('#debug-port').value=744; $('#ftp-port').value=2121; $('#firmware-profile').value=e.target.value==='ps5'?'13.60':'auto'; }
    if (e.target.id === 'process') { state.pid = Number(e.target.value); state.session = null; state.results = null; state.hex = null; state.selected.clear(); if (state.pid) await refreshMaps(); else state.maps = []; renderPage(); }
    if (e.target.dataset.region) { if (e.target.checked) state.selected.add(e.target.dataset.region); else state.selected.delete(e.target.dataset.region); }
    if (e.target.id === 'scan-source') { state.dumpId = e.target.value; state.session = null; state.results = null; state.hex = null; $('#scan-results').innerHTML = resultsView(); $('#hex-output').innerHTML = hexView(); }
    if (e.target.id === 'mcp-writes') { await api('mcp_settings', { writes: e.target.checked }); toast(e.target.checked ? 'MCP verified writes enabled for this connection' : 'MCP writes disabled'); }
  } catch (err) { toast(err.message, true); }
});
state.status = await api('status'); state.dumps = await api('dump_list'); state.watches = await api('watch_list');
state.config = window.desktop ? await window.desktop.mcpConfig() : { mcpServers: { 'ps-neighborhood': { command: 'node', args: ['C:/path/to/ps-neighborhood/src/mcp.mjs'] } } };
shell();
let polling = false, watchCounter = 0;
setInterval(async () => {
  if (polling) return; polling = true;
  try {
    const previousConnection=state.status.connectionId;
    state.status = await api('status'); updateBadge();
    if(previousConnection&&previousConnection!==state.status.connectionId){
      state.processes=state.status.mode==='disconnected'?[]:await api('processes');state.pid=0;state.maps=[];state.selected.clear();
      if(!state.dumpId){state.session=null;state.results=null;state.hex=null;state.previousHex=null;}
      $('#process').innerHTML=processOptions();if(['home','memory','map'].includes(state.page))renderPage();
    }
    if (state.page === 'console') {const c=await api('console_status');if(JSON.stringify(c)!==JSON.stringify(state.console)){state.console=c;paintConsole();}}
    if (state.page === 'shadow'&&isPS5()) await refreshShadow();
    if (state.page === 'pkg') { state.pkg = await api('pkg_status', { refresh: watchCounter % 5 === 0 }); if ($('#pkg-progress')) $('#pkg-progress').innerHTML = packageProgress(); if($('#pkg-queue'))$('#pkg-queue').innerHTML=packageQueueView(); }
    if ($('#scan-progress')) $('#scan-progress').innerHTML = progress(state.status.scan);
    if ($('#dump-progress')) $('#dump-progress').innerHTML = progress(state.status.dump);
    if ($('#pointer-progress')) $('#pointer-progress').innerHTML = progress(state.status.pointers);
    const scan = state.status.scan, dump = state.status.dump;
    if (scan && scan.state !== 'running' && scan.id !== state.lastScan) {
      state.lastScan = scan.id;
      if (scan.state === 'complete') { state.session = scan.sessionId; state.offset = 0; await getResults(); toast(`${scan.matches.toLocaleString()} candidates · ${(scan.elapsedMs / 1000).toFixed(1)}s`); }
      else if (scan.error) toast(scan.error, scan.state === 'failed');
    }
    if (dump && dump.state !== 'running' && dump.id !== state.lastDump) {
      state.lastDump = dump.id;
      if (dump.state === 'complete') { state.dumps = await api('dump_list'); if (state.page === 'dump') renderPage(); toast('RAM bundle ready for Ghidra · ' + fmt(dump.bytes)); }
      else if (dump.error) toast(dump.error, dump.state === 'failed');
    }
    if ($('#transfer-status') && state.status.transfer) $('#transfer-status').textContent = `${state.status.transfer.state} · ${fmt(state.status.transfer.bytes)} · ${state.status.transfer.remote}`;
    if (++watchCounter % 2 === 0 && $('#watch-live')?.checked && scan?.state !== 'running' && dump?.state !== 'running') await handlers['watch-refresh']();
  } catch {} finally { polling = false; }
}, 1000);
